"""Shared: the hierarchical player model. y_ij = X_ij . beta_i + e,  beta_i ~ N(mu, Sigma),  e ~ N(0, s2 / w)."""
import numpy as np
MINPOP = 60
def suff(pid, X, y, w, mult=None):
    u, inv = np.unique(pid, return_inverse=True); P, p = len(u), X.shape[1]; mult = np.ones(len(y)) if mult is None else mult; w = w * mult
    A = np.zeros((P, p, p)); c = np.zeros((P, p)); yy = np.bincount(inv, w * y * y, P); cnt = np.bincount(inv, mult, P)
    for a in range(p):
        c[:, a] = np.bincount(inv, w * X[:, a] * y, P)
        for d in range(p): A[:, a, d] = np.bincount(inv, w * X[:, a] * X[:, d], P)
    return u, A, c, yy, cnt
def estep(A, c, mu, Sig, s2):
    Si = np.linalg.inv(Sig); S = np.linalg.inv(Si[None] + A / s2); return np.einsum("ipq,iq->ip", S, (Si @ mu)[None] + c / s2), S
def fit(pid, X, y, w, mult=None, hyper=None, max_iter=30000, tol=1e-9):
    """Empirical Bayes by EM, run to convergence. With hyper=(mu, Sig, s2) the population is held fixed and only players are re-estimated."""
    u, A, c, yy, cnt = suff(pid, X, y, w, mult); p = X.shape[1]
    if hyper is not None:
        m, S = estep(A, c, *hyper); return dict(ids=u, m=m, S=S, mu=hyper[0], Sig=hyper[1], s2=hyper[2], cnt=cnt, iters=0)
    pop = cnt >= MINPOP; N = cnt[pop].sum(); mu = np.zeros(p); Sig = np.eye(p) * 0.01; s2 = yy.sum() / max(cnt.sum(), 1)
    for it in range(max_iter):
        m, S = estep(A, c, mu, Sig, s2); mp, Sp = m[pop], S[pop]; mu = mp.mean(0); D = mp - mu
        new = (D.T @ D + Sp.sum(0)) / pop.sum() + 1e-10 * np.eye(p)
        s2 = (yy[pop] - 2 * (mp * c[pop]).sum(1) + np.einsum("ipq,ipq->i", A[pop], mp[:, :, None] * mp[:, None, :] + Sp)).sum() / N
        done = np.abs(new - Sig).max() < tol * max(np.abs(Sig).max(), 1e-12); Sig = new
        if done and it > 50: break
    m, S = estep(A, c, mu, Sig, s2)
    return dict(ids=u, m=m, S=S, mu=mu, Sig=Sig, s2=s2, cnt=cnt, iters=it + 1)
